package io.dndroll.backup;
import java.nio.file.*;import java.sql.*;import java.util.*;import java.io.IOException;
import tools.jackson.databind.json.JsonMapper;
/** Offline and private. Never executes an old command. */
public final class CampaignEvidenceGraphCommand {
 public static CampaignEvidenceGraph.Report inspect(Path archive,String url,String username,String password,Path assets,UUID campaign)throws IOException{
  try(var c=DriverManager.getConnection(url,username,password)){c.setReadOnly(true);c.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);c.setAutoCommit(false);
   if(!RecoveryAuditCommand.inspect(c,archive,assets,RecoveryInventory.Mode.SAME_ID).result().status().equals("VERIFIED"))throw new IOException();
   try(var s=c.prepareStatement("select 1 from campaign where id=?")){s.setObject(1,campaign);try(var rs=s.executeQuery()){if(!rs.next())throw new IOException();}}
   var rows=read(c,campaign);var receipts=new ArrayList<CampaignEvidenceGraph.SourceReceipt>();try(var st=c.prepareStatement("select result_id,fingerprint,actor from dice_command_receipt where campaign_id=?")){st.setObject(1,campaign);try(var rs=st.executeQuery()){while(rs.next())receipts.add(new CampaignEvidenceGraph.SourceReceipt(rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3)));}}var report=CampaignEvidenceGraph.inspect(campaign,rows,receipts);c.rollback();return report;
  }catch(Exception e){throw new IOException("Evidence inspection failed; verify isolated archive, database, assets and capacity");}
 }
 static List<CampaignEvidenceGraph.Row> read(Connection c,UUID campaign)throws Exception{
  var rows=new ArrayList<CampaignEvidenceGraph.Row>();var json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,tools.jackson.databind.DeserializationFeature.FAIL_ON_MISSING_CREATOR_PROPERTIES,tools.jackson.databind.DeserializationFeature.FAIL_ON_NULL_FOR_PRIMITIVES).build();
  for(String table:new TreeSet<>(CampaignEvidenceGraph.TYPES.keySet())){if(table.equals("character_history_before"))continue;
   if(table.equals("character_card")){try(var s=c.prepareStatement("select * from character_card where campaign_id=?")){s.setObject(1,campaign);try(var r=s.executeQuery()){while(r.next()){UUID id=r.getObject("id",UUID.class);var controllers=new ArrayList<String>();try(var q=c.prepareStatement("select username from character_controller where character_id=? order by username")){q.setObject(1,id);try(var users=q.executeQuery()){while(users.next())controllers.add(users.getString(1));}}
    var card=new io.dndroll.application.CharacterService.Card(id,campaign,r.getLong("version"),r.getBoolean("hidden"),r.getBoolean("share_full"),r.getBoolean("import_review"),controllers,json.readValue(r.getString("sheet"),io.dndroll.domain.CharacterSheet.class));rows.add(new CampaignEvidenceGraph.Row(table,id,card.version(),null,null,null,null,json.writeValueAsString(card)));}}}continue;}
   if(table.equals("character_history")){try(var s=c.prepareStatement("select h.* from character_history h join character_card a on a.id=h.character_id where a.campaign_id=? order by h.character_id,h.version")){s.setObject(1,campaign);try(var r=s.executeQuery()){while(r.next()){UUID id=r.getObject("character_id",UUID.class);rows.add(new CampaignEvidenceGraph.Row(table,id,r.getLong("version"),null,null,null,null,r.getString("after_state")));if(r.getString("before_state")!=null){var b=json.readValue(r.getString("before_state"),io.dndroll.application.CharacterService.Card.class);rows.add(new CampaignEvidenceGraph.Row("character_history_before",id,r.getLong("version")-1,null,null,null,null,r.getString("before_state")));}}}}continue;}
   var columns=CampaignRemapPlan.columns(table);var names=new HashSet<String>();columns.forEach(col->names.add(col.name()));
   String blob=names.contains("snapshot")?"snapshot":"data",id=names.contains("target_id")&&!names.contains("id")?"target_id":"id";
   try(var s=c.prepareStatement("select * from public.\""+table+"\" where campaign_id=?")){s.setObject(1,campaign);try(var r=s.executeQuery()){while(r.next()){rows.add(new CampaignEvidenceGraph.Row(table,r.getObject(id,UUID.class),names.contains("version")?r.getLong("version"):-1,names.contains("origin_version")?r.getLong("origin_version"):null,names.contains("damage_version")?r.getLong("damage_version"):null,names.contains("character_id")?r.getObject("character_id",UUID.class):null,names.contains("id")&&names.contains("target_id")?r.getObject("target_id",UUID.class):null,r.getString(blob)));if(rows.size()>100000)throw new IOException();}}}
  }
  try(var s=c.prepareStatement("select id,message_id,roll_id,action_id from timeline_entry where campaign_id=?")){s.setObject(1,campaign);try(var r=s.executeQuery()){while(r.next()){int owners=0;for(int i=2;i<=4;i++){UUID owner=r.getObject(i,UUID.class);if(owner!=null){owners++;if(!owner.equals(r.getObject(1,UUID.class)))throw new IOException();}}if(owners!=1)throw new IOException();}}}
  return rows;
 }
 public static void main(String[] args){try{if(args.length!=5||!args[4].equals("REVIEW_ONLY"))throw new IOException();Path output=Path.of(args[2]);if(Files.exists(output,LinkOption.NOFOLLOW_LINKS))throw new IOException();var p=inspect(Path.of(args[0]),System.getenv("RECOVERY_AUDIT_DATABASE_URL"),System.getenv("RECOVERY_AUDIT_DATABASE_USERNAME"),System.getenv("RECOVERY_AUDIT_DATABASE_PASSWORD"),Path.of(args[1]),UUID.fromString(args[3]));Files.write(output,JsonMapper.builder().build().writeValueAsBytes(p),StandardOpenOption.CREATE_NEW);System.out.println("EVIDENCE REVIEW BLOCKED: consistent="+p.consistent()+"; executable=false; no campaign created");System.exit(2);}catch(Exception e){System.err.println("EVIDENCE REVIEW FAILED: verify isolated inputs and new output path; source fence unchanged");System.exit(1);}}
}
